 		fes.getHtmlToDisplay();  


 		List<FormSubmissionError> validationErrors = fes.getSubmissionController().validateSubmission(fes.getContext(),
 		    request);
 		if (validationErrors.size() > 0) {
 			return returnHelper(validationErrors, fes, null);
