public class main {
public void send(final int iCode, final String iReason, final String iContentType, final Object iContent, final String iHeaders)
      throws IOException {
   if (sendStarted)

   {
      return;
    }
    sendStarted = true;




    if (callbackFunction != null) {
      content = callbackFunction + "(" + iContent + ")";
      contentType = "text/javascript";
    } else {
      if (content == null || content.length() == 0) {
        content = iContent != null ? iContent.toString() : null;
      }
      if (contentType == null || contentType.length() == 0) {
        contentType = iContentType;
      }
    }

    final boolean empty = content == null || content.length() == 0;

    if (this.code > 0) {
      writeStatus(this.code, iReason);
    } else {
      writeStatus(empty && iCode == 200 ? 204 : iCode, iReason);
    }
    writeHeaders(contentType, keepAlive);

    if (iHeaders != null) {
      writeLine(iHeaders);
    }

    if (sessionId != null)
      writeLine("Set-Cookie: " + OHttpUtils.OSESSIONID + "=" + sessionId + "; Path=/; HttpOnly");

    byte[] binaryContent = null;
    if (!empty) {
      if (contentEncoding != null && contentEncoding.equals(OHttpUtils.CONTENT_ACCEPT_GZIP_ENCODED)) {
        binaryContent = compress(content);
      } else {
        binaryContent = content.getBytes(utf8);
      }
    }

    writeLine(OHttpUtils.HEADER_CONTENT_LENGTH + (empty ? 0 : binaryContent.length));

    writeLine(null);

    if (binaryContent != null) {
      out.write(binaryContent);
    }

    flush();
  }
}

public class main {
private Document getDocument(final InputStream input) throws SAXException {
    try {
      final DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
      factory.setValidating(true);

      factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

      final String dtdFile = "/games/strategy/engine/xml/" + DTD_FILE_NAME;
      final URL url = GameParser.class.getResource(dtdFile);
      if (url == null) {
        throw new RuntimeException(String.format("Map: %s, Could not find in classpath %s", mapName, dtdFile));
      }
      final DocumentBuilder builder = factory.newDocumentBuilder();
      builder.setErrorHandler(new ErrorHandler() {
        @Override
        public void fatalError(final SAXParseException exception) {
          errorsSax.add(exception);
        }

        @Override
        public void error(final SAXParseException exception) {
          errorsSax.add(exception);
        }

        @Override
        public void warning(final SAXParseException exception) {
          errorsSax.add(exception);
        }
      });
      final String dtdSystem = url.toExternalForm();
      final String system = dtdSystem.substring(0, dtdSystem.length() - DTD_FILE_NAME.length());
      return builder.parse(input, system);
    } catch (final IOException | ParserConfigurationException e) {
      throw new IllegalStateException("Error parsing: " + mapName, e);
    }
