void SoftMP3::onQueueFilled(OMX_U32  ) {
 if (mSignalledError || mOutputPortSettingsChange != NONE) {
 return;
 }

 List<BufferInfo *> &inQueue = getPortQueue(0);
 List<BufferInfo *> &outQueue = getPortQueue(1);

 while ((!inQueue.empty() || (mSawInputEos && !mSignalledOutputEos)) && !outQueue.empty()) {
 BufferInfo *inInfo = NULL;
        OMX_BUFFERHEADERTYPE *inHeader = NULL;
 if (!inQueue.empty()) {
            inInfo = *inQueue.begin();
            inHeader = inInfo->mHeader;
 }

 BufferInfo *outInfo = *outQueue.begin();
        OMX_BUFFERHEADERTYPE *outHeader = outInfo->mHeader;
        outHeader->nFlags = 0;

 if (inHeader) {
 if (inHeader->nOffset == 0 && inHeader->nFilledLen) {
                mAnchorTimeUs = inHeader->nTimeStamp;
                mNumFramesOutput = 0;
 }

 if (inHeader->nFlags & OMX_BUFFERFLAG_EOS) {
                mSawInputEos = true;
 }

            mConfig->pInputBuffer =
                inHeader->pBuffer + inHeader->nOffset;

            mConfig->inputBufferCurrentLength = inHeader->nFilledLen;
 } else {
            mConfig->pInputBuffer = NULL;
            mConfig->inputBufferCurrentLength = 0;
 }
        mConfig->inputBufferMaxLength = 0;

         mConfig->inputBufferUsedLength = 0;

         mConfig->outputFrameSize = kOutputBufferSize / sizeof(int16_t);

         mConfig->pOutputBuffer =
             reinterpret_cast<int16_t *>(outHeader->pBuffer);

        ERROR_CODE decoderErr;
 if ((decoderErr = pvmp3_framedecoder(mConfig, mDecoderBuf))
 != NO_DECODING_ERROR) {
            ALOGV("mp3 decoder returned error %d", decoderErr);

 if (decoderErr != NO_ENOUGH_MAIN_DATA_ERROR
 && decoderErr != SIDE_INFO_ERROR) {
                ALOGE("mp3 decoder returned error %d", decoderErr);

                notify(OMX_EventError, OMX_ErrorUndefined, decoderErr, NULL);
                mSignalledError = true;
 return;
 }

 if (mConfig->outputFrameSize == 0) {
                mConfig->outputFrameSize = kOutputBufferSize / sizeof(int16_t);
 }

 if (decoderErr == NO_ENOUGH_MAIN_DATA_ERROR && mSawInputEos) {
 if (!mIsFirst) {
                    outHeader->nOffset = 0;
                    outHeader->nFilledLen = kPVMP3DecoderDelay * mNumChannels * sizeof(int16_t);

                    memset(outHeader->pBuffer, 0, outHeader->nFilledLen);
 }
                outHeader->nFlags = OMX_BUFFERFLAG_EOS;
                mSignalledOutputEos = true;
 } else {

                ALOGV_IF(mIsFirst, "insufficient data for first frame, sending silence");
                memset(outHeader->pBuffer,
 0,
                       mConfig->outputFrameSize * sizeof(int16_t));

 if (inHeader) {
                    mConfig->inputBufferUsedLength = inHeader->nFilledLen;
 }
 }
 } else if (mConfig->samplingRate != mSamplingRate
 || mConfig->num_channels != mNumChannels) {
            mSamplingRate = mConfig->samplingRate;
            mNumChannels = mConfig->num_channels;

            notify(OMX_EventPortSettingsChanged, 1, 0, NULL);
            mOutputPortSettingsChange = AWAITING_DISABLED;
 return;
 }

 if (mIsFirst) {
            mIsFirst = false;
            outHeader->nOffset =
                kPVMP3DecoderDelay * mNumChannels * sizeof(int16_t);

            outHeader->nFilledLen =
                mConfig->outputFrameSize * sizeof(int16_t) - outHeader->nOffset;
 } else if (!mSignalledOutputEos) {
            outHeader->nOffset = 0;
            outHeader->nFilledLen = mConfig->outputFrameSize * sizeof(int16_t);
 }

        outHeader->nTimeStamp =
            mAnchorTimeUs + (mNumFramesOutput * 1000000ll) / mSamplingRate;

 if (inHeader) {
            CHECK_GE(inHeader->nFilledLen, mConfig->inputBufferUsedLength);

            inHeader->nOffset += mConfig->inputBufferUsedLength;
            inHeader->nFilledLen -= mConfig->inputBufferUsedLength;


 if (inHeader->nFilledLen == 0) {
                inInfo->mOwnedByUs = false;
                inQueue.erase(inQueue.begin());
                inInfo = NULL;
                notifyEmptyBufferDone(inHeader);
                inHeader = NULL;
 }
 }

        mNumFramesOutput += mConfig->outputFrameSize / mNumChannels;

        outInfo->mOwnedByUs = false;
        outQueue.erase(outQueue.begin());
        outInfo = NULL;
        notifyFillBufferDone(outHeader);
        outHeader = NULL;
 }
}

const BlockEntry* Segment::GetBlock(const CuePoint& cp,
 const CuePoint::TrackPosition& tp) {
 Cluster** const ii = m_clusters;
 Cluster** i = ii;

 const long count = m_clusterCount + m_clusterPreloadCount;

 Cluster** const jj = ii + count;
 Cluster** j = jj;

 while (i < j) {

 Cluster** const k = i + (j - i) / 2;
    assert(k < jj);

 Cluster* const pCluster = *k;
    assert(pCluster);


 const long long pos = pCluster->GetPosition();
    assert(pos >= 0);

 if (pos < tp.m_pos)
      i = k + 1;
 else if (pos > tp.m_pos)
      j = k;
 else
 return pCluster->GetEntry(cp, tp);
 }

  assert(i == j);


   Cluster* const pCluster = Cluster::Create(this, -1, tp.m_pos);   
 assert(pCluster);

   const ptrdiff_t idx = i - m_clusters;

 PreloadCluster(pCluster, idx);
   assert(m_clusters);
   assert(m_clusterPreloadCount > 0);
   assert(m_clusters[idx] == pCluster);

 return pCluster->GetEntry(cp, tp);
}

 long Cluster::ParseBlockGroup(long long payload_size, long long& pos,
  long& len) {
  const long long payload_start = pos;
  const long long payload_stop = pos + payload_size;

  IMkvReader* const pReader = m_pSegment->m_pReader;

  long long total, avail;

  long status = pReader->Length(&total, &avail);

  if (status < 0)  
  return status;

   assert((total < 0) || (avail <= total));

  if ((total >= 0) && (payload_stop > total))
  return E_FILE_FORMAT_INVALID;

  if (payload_stop > avail) {
     len = static_cast<long>(payload_size);
  return E_BUFFER_NOT_FULL;
  }

  long long discard_padding = 0;

  while (pos < payload_stop) {

  if ((pos + 1) > avail) {
       len = 1;
  return E_BUFFER_NOT_FULL;
  }

  long long result = GetUIntLength(pReader, pos, len);

  if (result < 0)  
  return static_cast<long>(result);

  if (result > 0)  
  return E_BUFFER_NOT_FULL;

  if ((pos + len) > payload_stop)
  return E_FILE_FORMAT_INVALID;

  if ((pos + len) > avail)
  return E_BUFFER_NOT_FULL;

  const long long id = ReadUInt(pReader, pos, len);

  if (id < 0)  
  return static_cast<long>(id);

  if (id == 0)  
  return E_FILE_FORMAT_INVALID;

     pos += len;  


  if ((pos + 1) > avail) {
       len = 1;
  return E_BUFFER_NOT_FULL;
  }

     result = GetUIntLength(pReader, pos, len);

  if (result < 0)  
  return static_cast<long>(result);

  if (result > 0)  
  return E_BUFFER_NOT_FULL;

  if ((pos + len) > payload_stop)
  return E_FILE_FORMAT_INVALID;

  if ((pos + len) > avail)
  return E_BUFFER_NOT_FULL;

  const long long size = ReadUInt(pReader, pos, len);

  if (size < 0)  
  return static_cast<long>(size);

     pos += len;  


  if (pos > payload_stop)
  return E_FILE_FORMAT_INVALID;

  if (size == 0)  
  continue;

  const long long unknown_size = (1LL << (7 * len)) - 1;

  if (size == unknown_size)
  return E_FILE_FORMAT_INVALID;

  if (id == 0x35A2) {  
       status = UnserializeInt(pReader, pos, size, discard_padding);

  if (status < 0)  
  return status;
  }

  if (id != 0x21) {  
       pos += size;  

  if (pos > payload_stop)
  return E_FILE_FORMAT_INVALID;

  continue;
  }

  const long long block_stop = pos + size;

  if (block_stop > payload_stop)
  return E_FILE_FORMAT_INVALID;


  if ((pos + 1) > avail) {
       len = 1;
  return E_BUFFER_NOT_FULL;
  }

     result = GetUIntLength(pReader, pos, len);

  if (result < 0)  
  return static_cast<long>(result);

  if (result > 0)  
  return E_BUFFER_NOT_FULL;

  if ((pos + len) > block_stop)
  return E_FILE_FORMAT_INVALID;

  if ((pos + len) > avail)
  return E_BUFFER_NOT_FULL;

  const long long track = ReadUInt(pReader, pos, len);

  if (track < 0)  
  return static_cast<long>(track);


      if (track == 0)
        return E_FILE_FORMAT_INVALID;

#if 0
        const Tracks* const pTracks = m_pSegment->GetTracks();
        assert(pTracks);
        const long tn = static_cast<long>(track);
        const Track* const pTrack = pTracks->GetTrackByNumber(tn);
        if (pTrack == NULL)
            return E_FILE_FORMAT_INVALID;
#endif
      pos += len;   

      if ((pos + 2) > block_stop)
  return E_FILE_FORMAT_INVALID;

  if ((pos + 2) > avail) {
       len = 2;
  return E_BUFFER_NOT_FULL;
  }

     pos += 2;  

  if ((pos + 1) > block_stop)
  return E_FILE_FORMAT_INVALID;

  if ((pos + 1) > avail) {
       len = 1;
  return E_BUFFER_NOT_FULL;
  }

  unsigned char flags;

     status = pReader->Read(pos, 1, &flags);

  if (status < 0) {  
       len = 1;
  return status;
  }

  ++pos;  
     assert(pos <= avail);

  if (pos >= block_stop)
  return E_FILE_FORMAT_INVALID;

  const int lacing = int(flags & 0x06) >> 1;

  if ((lacing != 0) && (block_stop > avail)) {
       len = static_cast<long>(block_stop - pos);
  return E_BUFFER_NOT_FULL;

      }

      pos = block_stop;   
    assert(pos <= payload_stop);
    }

  assert(pos == payload_stop);

    status = CreateBlock(0x20,   
                         payload_start, payload_size, discard_padding);
  if (status != 0)
  return status;

   m_pos = payload_stop;

  return 0;  
 }

 chdlc_print(netdissect_options *ndo, register const u_char *p, u_int length)
 {
 	u_int proto;

 	proto = EXTRACT_16BITS(&p[2]);
 	if (ndo->ndo_eflag) {
                 ND_PRINT((ndo, "%s, ethertype %s (0x%04x), length %u: ",
                       tok2str(chdlc_cast_values, "0x%02x", p[0]),
                       tok2str(ethertype_values, "Unknown", proto),
                       proto,
                       length));
	}

	length -= CHDLC_HDRLEN;
	p += CHDLC_HDRLEN;

	switch (proto) {
	case ETHERTYPE_IP:
		ip_print(ndo, p, length);
		break;
	case ETHERTYPE_IPV6:
		ip6_print(ndo, p, length);
		break;
	case CHDLC_TYPE_SLARP:
		chdlc_slarp_print(ndo, p, length);
		break;
#if 0
	case CHDLC_TYPE_CDP:
		chdlc_cdp_print(p, length);
		break;
#endif
        case ETHERTYPE_MPLS:
        case ETHERTYPE_MPLS_MULTI:
                mpls_print(ndo, p, length);
 		break;
         case ETHERTYPE_ISO:

                 if (*(p+1) == 0x81 ||
                     *(p+1) == 0x82 ||
                     *(p+1) == 0x83)
                    isoclns_print(ndo, p + 1, length - 1, ndo->ndo_snapend - p - 1);
                else
                    isoclns_print(ndo, p, length, ndo->ndo_snapend - p);
                break;
	default:
                if (!ndo->ndo_eflag)
                        ND_PRINT((ndo, "unknown CHDLC protocol (0x%04x)", proto));
                break;
 	}

 	return (CHDLC_HDRLEN);
 }

xps_select_best_font_encoding(xps_font_t *font)
{
    static struct { int pid, eid; } xps_cmap_list[] =
    {
        { 3, 10 },       
        { 3, 1 },        
        { 3, 5 },        
        { 3, 4 },        
        { 3, 3 },        
        { 3, 2 },        
        { 3, 0 },        
        { 1, 0 },
        { -1, -1 },
    };

    int i, k, n, pid, eid;

    n = xps_count_font_encodings(font);
    for (k = 0; xps_cmap_list[k].pid != -1; k++)
    {
        for (i = 0; i < n; i++)
        {
             xps_identify_font_encoding(font, i, &pid, &eid);
             if (pid == xps_cmap_list[k].pid && eid == xps_cmap_list[k].eid)
             {
               xps_select_font_encoding(font, i);
               return;
             }
         }
     }

    gs_warn("could not find a suitable cmap");
}

 int usb_get_bos_descriptor(struct usb_device *dev)
 {
 	struct device *ddev = &dev->dev;
 	struct usb_bos_descriptor *bos;
 	struct usb_dev_cap_header *cap;
 	unsigned char *buffer;
 	int length, total_len, num, i;
 	int ret;

 	bos = kzalloc(sizeof(struct usb_bos_descriptor), GFP_KERNEL);
 	if (!bos)
 		return -ENOMEM;


 	ret = usb_get_descriptor(dev, USB_DT_BOS, 0, bos, USB_DT_BOS_SIZE);
 	if (ret < USB_DT_BOS_SIZE) {
 		dev_err(ddev, "unable to get BOS descriptor\n");
 		if (ret >= 0)
 			ret = -ENOMSG;
 		kfree(bos);
 		return ret;
 	}

 	length = bos->bLength;
 	total_len = le16_to_cpu(bos->wTotalLength);
 	num = bos->bNumDeviceCaps;
 	kfree(bos);
 	if (total_len < length)
 		return -EINVAL;

 	dev->bos = kzalloc(sizeof(struct usb_host_bos), GFP_KERNEL);
 	if (!dev->bos)
 		return -ENOMEM;


 	buffer = kzalloc(total_len, GFP_KERNEL);
 	if (!buffer) {
 		ret = -ENOMEM;
 		goto err;
 	}
 	dev->bos->desc = (struct usb_bos_descriptor *)buffer;

 	ret = usb_get_descriptor(dev, USB_DT_BOS, 0, buffer, total_len);
 	if (ret < total_len) {
 		dev_err(ddev, "unable to get BOS descriptor set\n");
 		if (ret >= 0)
 			ret = -ENOMSG;
 		goto err;
 	}
 	total_len -= length;

  	for (i = 0; i < num; i++) {
  		buffer += length;
  		cap = (struct usb_dev_cap_header *)buffer;
		length = cap->bLength;

		if (total_len < length)
  			break;
  		total_len -= length;

  		if (cap->bDescriptorType != USB_DT_DEVICE_CAPABILITY) {
 			dev_warn(ddev, "descriptor type invalid, skip\n");
 			continue;
 		}

 		switch (cap->bDevCapabilityType) {
 		case USB_CAP_TYPE_WIRELESS_USB:

 			break;
 		case USB_CAP_TYPE_EXT:
 			dev->bos->ext_cap =
 				(struct usb_ext_cap_descriptor *)buffer;
 			break;
 		case USB_SS_CAP_TYPE:
 			dev->bos->ss_cap =
 				(struct usb_ss_cap_descriptor *)buffer;
 			break;
 		case USB_SSP_CAP_TYPE:
 			dev->bos->ssp_cap =
 				(struct usb_ssp_cap_descriptor *)buffer;
 			break;
 		case CONTAINER_ID_TYPE:
 			dev->bos->ss_id =
 				(struct usb_ss_container_id_descriptor *)buffer;
 			break;
 		case USB_PTM_CAP_TYPE:
 			dev->bos->ptm_cap =
 				(struct usb_ptm_cap_descriptor *)buffer;
 		default:
 			break;
 		}
 	}

 	return 0;

 err:
 	usb_release_bos_descriptor(dev);
 	return ret;
 }

