 static int splice_pipe_to_pipe(struct pipe_inode_info *ipipe,
 			       struct pipe_inode_info *opipe,
 			       size_t len, unsigned int flags)
 {
 	struct pipe_buffer *ibuf, *obuf;
 	int ret = 0, nbuf;
 	bool input_wakeup = false;


 retry:
 	ret = ipipe_prep(ipipe, flags);
 	if (ret)
 		return ret;

 	ret = opipe_prep(opipe, flags);
 	if (ret)
 		return ret;


 	pipe_double_lock(ipipe, opipe);

 	do {
 		if (!opipe->readers) {
 			send_sig(SIGPIPE, current, 0);
 			if (!ret)
 				ret = -EPIPE;
 			break;
 		}

 		if (!ipipe->nrbufs && !ipipe->writers)
 			break;


 		if (!ipipe->nrbufs || opipe->nrbufs >= opipe->buffers) {

 			if (ret)
 				break;

 			if (flags & SPLICE_F_NONBLOCK) {
 				ret = -EAGAIN;
 				break;
 			}


 			pipe_unlock(ipipe);
 			pipe_unlock(opipe);
 			goto retry;
 		}

 		ibuf = ipipe->bufs + ipipe->curbuf;
 		nbuf = (opipe->curbuf + opipe->nrbufs) & (opipe->buffers - 1);
 		obuf = opipe->bufs + nbuf;

 		if (len >= ibuf->len) {

 			*obuf = *ibuf;
 			ibuf->ops = NULL;
 			opipe->nrbufs++;
 			ipipe->curbuf = (ipipe->curbuf + 1) & (ipipe->buffers - 1);
 			ipipe->nrbufs--;
 			input_wakeup = true;
 		} else {

			pipe_buf_get(ipipe, ibuf);
  			*obuf = *ibuf;


 			obuf->flags &= ~PIPE_BUF_FLAG_GIFT;

 			pipe_buf_mark_unmergeable(obuf);

 			obuf->len = len;
 			opipe->nrbufs++;
 			ibuf->offset += obuf->len;
 			ibuf->len -= obuf->len;
 		}
 		ret += obuf->len;
 		len -= obuf->len;
 	} while (len);

 	pipe_unlock(ipipe);
 	pipe_unlock(opipe);


 	if (ret > 0)
 		wakeup_pipe_readers(opipe);

 	if (input_wakeup)
 		wakeup_pipe_writers(ipipe);

 	return ret;
 }

 void PlatformSensorProviderMac::CreateSensorInternal(
     mojom::SensorType type,
   mojo::ScopedSharedBufferMapping mapping,
     const CreateSensorCallback& callback) {
   switch (type) {
     case mojom::SensorType::AMBIENT_LIGHT: {
       scoped_refptr<PlatformSensor> sensor =
         new PlatformSensorAmbientLightMac(std::move(mapping), this);
       callback.Run(std::move(sensor));
       break;
     }
     case mojom::SensorType::ACCELEROMETER: {
       callback.Run(base::MakeRefCounted<PlatformSensorAccelerometerMac>(
         std::move(mapping), this));
       break;
     }
     case mojom::SensorType::RELATIVE_ORIENTATION_EULER_ANGLES: {
       auto fusion_algorithm = std::make_unique<
           RelativeOrientationEulerAnglesFusionAlgorithmUsingAccelerometer>();
     PlatformSensorFusion::Create(std::move(mapping), this,
                                    std::move(fusion_algorithm), callback);
       break;
     }
    case mojom::SensorType::RELATIVE_ORIENTATION_QUATERNION: {
      auto orientation_quaternion_fusion_algorithm_using_euler_angles =
          std::make_unique<
              OrientationQuaternionFusionAlgorithmUsingEulerAngles>(
              false  );
       PlatformSensorFusion::Create(
         std::move(mapping), this,
           std::move(orientation_quaternion_fusion_algorithm_using_euler_angles),
           callback);
       break;
    }
    default:
      callback.Run(nullptr);
  }
}

